#include "ctl_dl_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void ctl_dl_defer_action(Ctl_Dl_Action action, Ctl_Dl_Condition cond_ign, Ctl_Dl_Condition cond_gwr, UInt16 delay)
{
	ctl_dl_action = action;
	ctl_dl_cond_ign = cond_ign;
	ctl_dl_cond_gwr = cond_gwr;
	timeout_update(ctl_dl_defer_timeout, delay);
	timeout_start(ctl_dl_defer_timeout);
}

